<script lang="ts">    import {blur} from "svelte/transition";    const {data} = $props();    const imgs = $derived(data.signedUrls)    let open = $state(false);    let selected: typeof imgs[number] = $state(null);</script><svelte:head>    <title>Certificates</title>    <meta name="robots" content="noindex, nofollow"></svelte:head>{#if open && selected}    <div transition:blur onclick={() => {open = false;}}         onkeydown={() => {open = false;}}         role="button"         aria-label="img modal" tabindex="0"         class={`lightbox ${selected ? 'lightbox-visible' : 'lightbox-hidden'}`}>        <img src={selected.src} alt={selected.name}/>    </div>{/if}<main class="gallery">    {#each imgs as img}        <div onclick={() => {open = true; selected = img;}}             onkeydown={() => {open = true; selected = img;}}             role="button" tabindex="0">            <img src={img.src} alt={"certificate image: " + img.name}/>        </div>    {/each}</main><style>    .lightbox {        position: fixed;        left: 0;        top: 0;        width: 100vw;        height: 100vh;        background-color: rgba(0, 0, 0, 0.7);        z-index: 999;        display: grid;        place-items: center;        & img {            width: auto;            max-width: 90vw;            max-height: 90vh;            user-select: none;            user-drag: none;            -webkit-user-drag: none;        }    }    .gallery {        width: 100vw;        height: max-content;        overflow-y: auto;        background-color: #232323;        columns: 23vw;        box-sizing: border-box;        padding: 3rem 2rem;        & img {            width: 100%;            margin-bottom: 1rem;            transition: filter 0.1s ease-in-out;            user-select: none;            user-drag: none;            -webkit-user-drag: none;            &:hover {                cursor: pointer;                filter: brightness(0.7);            }        }    }</style>